 "welding_lede": "MAG-, TIG-, MMA- en SAW-processen — het juiste proces gekozen op basis van materiaal, dikte en toepassingseisen.",
 "welding_eyebrow": "01 / Keuzegids lasprocessen",
 "welding_h2": "Het juiste lasproces voor materiaal en toepassing.",
 "welding_cta_btn": "Projectadvies →",
