 "docs_intro_eyebrow": "Verifieerbaarheid",
 "docs_intro_h2": "Elk certificaat is het resultaat van een onafhankelijk auditproces",
 "docs_intro_p": "Wij delen al onze certificaten transparant met onze klanten en auditors. De documenten zijn in origineel PDF-formaat en kunnen rechtstreeks aan uw projectdossiers worden toegevoegd.",
