 "docs_cta_p": "Bezoek onze Kwaliteitspagina voor gedetailleerde informatie over traceerbaarheid, inspectieplannen en documentdiscipline.",
 "docs_cta_btn": "Kwaliteit & traceerbaarheid →",
 "sectors_h1": "Sectoren die wij<br/><span class=\"arc\">bedienen.</span>",
 "sectors_lede": "Van bouwmachines tot energie-infrastructuur, van drukvaten tot spoorwegmaterieel — productie die voldoet aan de normen van elke sector.",
 "sectors_s01_num": "// 01 · MACHINEBOUW",
 "sectors_s01_h2": "Machinebouw &<br/><span class=\"arc\">bouwmachines.</span>",
 "sectors_s01_desc": "Fabricage van bakken, chassis en machineframes uit HARDOX, Strenx en hoogsterktestaal. Gespecialiseerde WPS voor slijtvaste en hoogsterkte materialen.",
 "sectors_s02_num": "// 02 · STAALBOUW",
 "sectors_s02_h2": "Staalbouw &<br/><span class=\"arc\">industriële bouw.</span>",
 "sectors_s02_desc": "Bruggen, industriële gebouwconstructies en kraanbanen volgens EN 1090 EXC2/3.",
 "sectors_s03_num": "// 03 · PROCES & DRUKVATEN",
 "sectors_s03_h2": "Drukvaten &<br/><span class=\"arc\">procesapparatuur.</span>",
 "sectors_s03_desc": "Drukvaten en procestanks volgens PED cat. I–II. Volledig doorgelaste verbindingen, 100% NDO en CE-verklaring.",
 "sectors_s04_num": "// 04 · ENERGIE",
 "sectors_s04_h2": "Energie &<br/><span class=\"arc\">hernieuwbare infrastructuur.</span>",
 "sectors_s04_desc": "Zonnepaneelframes, windbeugels, generatorchassis. Stralen Sa 2½ + tweelaags coating voor 20+ jaar bescherming.",
 "sectors_s05_num": "// 05 · TRANSPORT & SPOOR",
 "sectors_s05_h2": "Transport, spoorsystemen<br/>&amp; <span class=\"arc\">defensie.</span>",
 "sectors_s05_desc": "Spoorwegconstructies volgens EN 15085 CL1/CL2, fabricage van HARDOX-pantsering voor defensietoepassingen.",
 "sectors_cta_h2": "Vraag een beoordeling op maat voor uw project.",
 "sectors_cta_lede": "Nieuwe vakgebieden betreden is voor ons een leermoment. Vertel ons over uw project, dan werken we samen aan de relevante norm.",
