 "home_svc_r1_name": "Gelaste constructiebouw",
 "home_svc_r1_brief": "Van S235 tot Strenx 1100, S690QL en S960QL tot HARDOX — betrouwbare productie in elke staalgroep, inclusief roestvast staal en aluminium, met goedgekeurde WPS.",
 "home_svc_r2_name": "Plaatsnijden & profielbewerking",
 "home_svc_r2_brief": "Koolstofstaal, roestvast staal, Hardox, Strenx en aluminium — tolerantiegecontroleerd snijden en lasklare voorbewerking volgens technische tekening.",
 "home_svc_r3_name": "Zetten & vormen",
 "home_svc_r3_brief": "V-zetten, U-vormen en cilindrisch walsen — geprogrammeerde beheersing van hoek, radius en montagepassing.",
 "home_svc_r4_name": "Mechanische montage & verzendvoorbereiding",
 "home_svc_r4_brief": "Subassemblage, aanhaalmomentregistratie en functionele tests — verzendverpakking geïntegreerd in het projectplan.",
 "home_svc_r5_name": "NDO & niet-destructief onderzoek",
 "home_svc_r5_brief": "4 onderzoeksmethoden in eigen huis, acceptatie volgens EN ISO 5817 klasse B — elke las gedocumenteerd, geen registratie overgeslagen.",
 "home_svc_r6_name": "Bouwmachineframes & bakken",
 "home_svc_r6_brief": "Fabricage van bakken, schalen, bladen en frames in slijtvast staal — inclusief seriemallen en MT-onderzoek.",
 "home_svc_r7_name": "Kraanbouw",
 "home_svc_r7_brief": "Fabricage van bovenloop-, zwenk- en monorailkraanconstructies — geleverd met FEM-sterkteberekening en CE-prestatieverklaring (DoP).",
 "home_svc_r8_name": "Drukvaten & procestanks",
 "home_svc_r8_brief": "Opslagtanks, reactievaten en warmtewisselaars volgens PED cat. I–II — compleet documentenpakket met RT + UT + CE-verklaring.",
 "trace_step_label": "STAP",
 "trace_step1_title": "Order & engineering",
 "trace_step1_dur": "1–3 dagen",
 "trace_step1_chip": "STAP 01 · SOP.REV.ENG",
 "trace_step1_h": "Technische tekening ontvangen, werkorder geopend.",
 "trace_step1_body": "DWG-/DXF-/PDF-bestanden van de klant worden beoordeeld door ons engineeringteam. Elke werkorder krijgt een uniek serienummer en in deze fase worden het productietraject, de WPS-keuze en het NDO-plan vastgelegd.",
 "trace_step1_d1": "Werkorder",
 "trace_step1_d2": "Productietekening",
 "trace_step1_d3": "WPS-keuze",
 "trace_step1_d4": "NDO-plan",
 "trace_step2_title": "Materiaalontvangst & smelt",
 "trace_step2_dur": "1 dag",
 "trace_step2_chip": "STAP 02 · MAT.INCOMING",
 "trace_step2_h": "Smeltnummer van de plaat geregistreerd met 3.1-certificaat.",
 "trace_step2_body": "S355 J2+N-plaat van Metalurji A.Ş.; smelt A41E2 geregistreerd met MTC-2026-4182 (EN 10204 3.1). Na VT en diktecontrole wordt de plaat gemarkeerd met werkorder JOB-A142.",
 "trace_step2_d1": "Materiaalcertificaat",
 "trace_step2_d2": "Visuele inspectie",
 "trace_step2_d3": "Diktemeting",
 "trace_step2_d4": "Smeltregistratie",
 "trace_step3_title": "Snijden & zetten",
 "trace_step3_dur": "1–2 dagen",
 "trace_step3_chip": "STAP 03 · CUT.FORM",
 "trace_step3_h": "CNC-snijden, tolerantiecontrole, zetten.",
 "trace_step3_body": "Platen worden volgens DXF met CNC-plasma of laser gesneden; profielen worden onder de juiste hoeken voorbereid. Zettingen worden gesimuleerd en onder de juiste hoek uitgevoerd. Elk onderdeel draagt fysiek het werkorder- + smeltnummer.",
 "trace_step3_d1": "Snijprogramma",
 "trace_step3_d2": "Maatrapport",
 "trace_step3_d3": "Controle zethoek",
 "trace_step3_d4": "Onderdeellabel",
 "trace_step4_title": "Gelaste constructiebouw",
 "trace_step4_dur": "3–10 dagen",
 "trace_step4_chip": "STAP 04 · WELDING.ACTIVE",
 "trace_step4_h": "Gecertificeerde lasser, goedgekeurde WPS.",
 "trace_step4_body": "Het lassen wordt uitsluitend uitgevoerd door lassers die voor die procedure gecertificeerd zijn. Elke lasnaad wordt digitaal geregistreerd met lassercode, WPS-nummer, aantal lagen en draad-/gasparameters. Voorwarm- en tussenlaagtemperaturen worden continu bewaakt.",
 "trace_step4_d1": "Lascertificaat",
 "trace_step4_d2": "WPS",
 "trace_step4_d3": "Laslogboek",
 "trace_step4_d4": "Tussenlaagtemperatuur",
 "trace_step5_title": "NDO / Inspectie",
 "trace_step5_dur": "1–3 dagen",
 "trace_step5_chip": "STAP 05 · NDT.INSPECT",
 "trace_step5_h": "Niet-destructief onderzoek: visueel, oppervlak, volumetrisch.",
 "trace_step5_body": "Volgens het NDO-plan: 100% visueel onderzoek (VT), penetrant (PT) of magnetisch onderzoek (MT) op kritische lassen, ultrasoon (UT) of radiografie (RT) voor volumetrische controle. Gerapporteerd door niveau II-personeel.",
 "trace_step5_d1": "VT-rapport",
 "trace_step5_d2": "PT/MT-rapport",
 "trace_step5_d3": "UT-rapport",
 "trace_step5_d4": "Acceptatiecriteria",
 "trace_step6_title": "Oppervlak & coating",
 "trace_step6_dur": "1–3 dagen",
 "trace_step6_chip": "STAP 06 · SURFACE.COAT",
 "trace_step6_h": "Stralen, primer, toplaag — C3/C4-bescherming.",
 "trace_step6_body": "Onderdelen worden voorbereid tot straalgraad Sa 2½; een verfsysteem passend bij de corrosiecategorie wordt aangebracht. De droge laagdikte (DFT) wordt bij elke laag gemeten en gerapporteerd.",
 "trace_step6_d1": "Straalgraad",
 "trace_step6_d2": "Verfsysteem",
 "trace_step6_d3": "DFT-meting",
 "trace_step6_d4": "Kleur / code",
 "trace_step7_title": "Verzending & dossier",
 "trace_step7_dur": "1 dag",
 "trace_step7_chip": "STAP 07 · SHIP.DOSSIER",
 "trace_step7_h": "Product + documentdossier samen geleverd.",
 "trace_step7_body": "Na de eindcontrole wordt het product verpakt. Een compleet documentenpakket gekoppeld aan de werkorder — WPS, WPQR, lascertificaten, materiaalcertificaten, NDO-rapporten, maat- en DFT-registraties, CE-verklaring — wordt in één dossier geleverd.",
 "trace_step7_d1": "Pakbon",
 "trace_step7_d2": "Documentdossier (pdf)",
 "trace_step7_d3": "CE / DoP",
 "trace_step7_d4": "QR-volgkaart",
