 "home_doc_eyebrow": "06 / Documentvoorbeeld",
 "home_doc_h2": "Elke levering bevat een <span style=\"color:var(--arc-2)\">dossier</span>: WPS, WPQR, NDO, tracering.",
 "home_doc_lede": "Wij leveren niet alleen onderdelen — bij elke zending leveren we een compleet documentdossier dat aantoont hoe het onderdeel is gefabriceerd, door wie het is gelast, welke grondstof is gebruikt en welke inspecties het heeft doorstaan.",
