 "testim_eyebrow": "02 / Stemmen van referenties",
 "testim_h2": "Feedback van klanten <span style=\"color:var(--arc-2)\">bevestigt de projectkwaliteit.</span>",
 "tm1_q": "Het was de eerste keer dat we met een leverancier werkten waarvan het documentenpakket zo compleet was. Bij de audit op locatie bleven er geen vraagtekens over — alle WPS-, NDO- en materiaalregistraties lagen klaar.",
 "tm1_role": "Kwaliteitsmanager · Energie-OEM",
 "tm2_q": "Voor de serieproductie van bakken verwachtten we zowel stiptheid als herhaalbare kwaliteit. ArmaWeld levert deze discipline al drie jaar consequent.",
 "tm2_role": "Inkoopmanager · OEM zwaar materieel",
 "tm3_q": "Bij ons drukvatproject werkten we met één team, van de ontwerpfase tot de CE-prestatieverklaring. De inbedrijfstelling verliep zonder problemen.",
 "tm3_role": "Projectingenieur · Chemische fabriek",
