 "about_flow_foot_l": "TOTAAL 05 STATIONS",
 "about_flow_foot_r": "● OPERATIONEEL",
 "quality_cert1_p": "Het fundamentele kwaliteitskader voor gelaste constructiebouw. Omvat toezicht door een lasingenieur, WPS, WPQR, lassercertificering, inspectieplan en volledige traceerbaarheid.",
 "quality_cert2_p": "Fabrieksproductiebeheersing (FPC) vereist voor de fabricage van dragende staalconstructies. EXC3 omvat constructies met grote gevolgen bij bezwijken.",
 "quality_cert3_p": "Ons kernmanagementkader, gebaseerd op procesmanagement, klantgerichtheid, risicogebaseerd denken en continue verbetering.",
 "quality_cert7_h3": "Milieumanagementsysteem",
 "quality_cert7_p": "Afvalbeheer, energie- en grondstofefficiëntie, beheersing van milieueffecten. Al het afval van snijden, lassen en oppervlaktebehandeling wordt geregistreerd en via erkende kanalen afgevoerd.",
 "quality_cert8_h3": "Managementsysteem voor gezond en veilig werken",
 "quality_cert8_p": "Risicobeoordeling, werkvergunningensystemen, PBM-beheer en werkplekaudits. Blootstelling aan lasrook, besloten ruimten en werken op hoogte worden procedureel beheerst.",
 "quality_cert4_p1": "<strong style=\"color:var(--bone)\">15614-1</strong> — WPQR voor booglassen van staal, nikkel en nikkellegeringen. Goedgekeurde procedures voor elke materiaalgroep van S235 tot Strenx 1100, inclusief drukvatstaal van de P-groep.",
 "quality_cert4_p2": "<strong style=\"color:var(--bone)\">15614-2</strong> — WPQR voor booglassen van aluminium en aluminiumlegeringen. Volledig doorgelaste stompe lassen in EN AW-5754 (AlMg3) en EN AW-6082 (AlSi1MgMn) met TIG (141).",
 "quality_cert5_p1": "<strong style=\"color:var(--bone)\">9606-1</strong> — Lasserkwalificatie voor staal en roestvast staal. Aparte bevoegdheden per proces (MAG 135, TIG 141, MMA 111), materiaalgroep, positie en dikte. Elke 6 maanden beoordeeld, elke 2 jaar vernieuwd.",
 "quality_cert5_p2": "<strong style=\"color:var(--bone)\">9606-2</strong> — TIG-lasserkwalificatie (141) voor aluminiumlegeringen. Geldig voor de groepen FM21 (Al-Mg) en FM22 (Al-Si-Mg) in de posities PA · PB · PF.",
 "quality_cert6_p": "Internationale kwalificatienorm voor personeel dat NDO-onderzoek uitvoert, interpreteert en rapporteert.",
 "quality_process_lede": "Traceerbaarheid gaat verloren zodra een van de volgende zeven schakels ontbreekt. In ons systeem kan geen enkele schakel beginnen zonder de registratie van de vorige.",
 "quality_pf1_t": "Technische intake",
 "quality_pf1_d": "Beoordeling van DWG/DXF/PDF, uitgifte van de werkorder en toekenning van het serienummer.",
 "quality_pf2_t": "Materiaalontvangst",
 "quality_pf2_d": "Smeltnummer + 3.1-certificaat + visuele inspectie. Markering van de plaat.",
 "quality_pf3_t": "Snijden & zetten",
 "quality_pf3_d": "CNC-snijden, maatcontrole, verificatie van de zethoek. Etikettering van onderdelen.",
 "quality_pf4_t": "Lasbewerking",
 "quality_pf4_d": "Gecertificeerde lasser + WPS + logboek tussenlaagtemperatuur.",
 "quality_pf5_t": "NDO-onderzoek",
 "quality_pf5_d": "Rapport door niveau 2-personeel + acceptatiecriterium EN ISO 5817 B.",
 "quality_pf6_t": "Oppervlak & verf",
