 "quality_kpi3_h": "Levering op tijd",
 "quality_kpi4_h": "Retourpercentage klanten",
 "quality_kpi1_delta": "▲ 0.4 pp — t.o.v. 2025",
 "quality_kpi2_delta": "▲ 0.9 pp",
 "quality_kpi3_delta": "▲ 2.1 pp",
 "quality_kpi4_delta": "▼ 0.2 pp — verbetering",
 "quality_cta_p": "Download het voorbeeld van het technisch dossier met WPS-samenvatting, WPQR-referentie, materiaalcertificaat en NDO-rapport. Bij elke projectlevering ontvangt u de ingevulde versie van dit pakket.",
 "quality_cta_note": "HTML · AFDRUKBAAR · VOORBEELDINHOUD",
 "quality_cta_btn_full": "Voorbeelddossier openen <span style=\"margin-left:8px;\">↓</span>",
 "ndt_scope_in_k": "IN EIGEN HUIS",
 "ndt_scope_in_sub": "Personeel gecertificeerd volgens ISO 9712 niveau II · rapportage in eigen huis · volledige traceerbaarheid",
 "ndt_scope_out_k": "UITBESTEED",
 "ndt_scope_out_sub": "Vereist een stralingsvergunning. Uitgevoerd met onze erkende, vergunde laboratoriumpartner — film-/digitale rapporten worden rechtstreeks in het projectdossier opgenomen.",
 "ndt_detects_h": "Gedetecteerde fouten",
 "ndt_vt_i": "// 01 · VT — VISUEEL ONDERZOEK",
 "ndt_vt_p": "De eerste, meest fundamentele en belangrijkste stap van elk onderzoek. De las wordt visueel beoordeeld met spiegels, ledlampen, lasmallen en digitale microscopen. Uitgevoerd bij 20 °C onder een verlichting van ≥ 350 lux.",
 "ndt_vt_sub": "Visuele inspectie",
 "ndt_vt_st1": "Oppervlaktereiniging & verlichtingsopstelling",
 "ndt_vt_st2": "Geometriecontrole vóór het lassen",
