 "ndt_vt_st4": "Eindinspectie (≥ 350 lux)",
 "ndt_vt_st5": "Meting & registratie",
 "ndt_vt_d1": "Oppervlaktescheuren (macro)",
 "ndt_vt_d2": "Afwijkingen in lasgeometrie (hoogte, lengte, rand)",
 "ndt_vt_d3": "Inkarteling",
 "ndt_vt_d4": "Spatten, oppervlaktedeuken, ruwheid",
 "ndt_vt_d5": "Uitlijnfouten van de verbinding, doorzakking",
 "ndt_vt_d6": "Fouten in de doorlassing (waar toegankelijk)",
 "ndt_vt_c1": "Oppervlaktegevoeligheid",
 "ndt_vt_c2": "Geometriecontrole",
 "ndt_pt_i": "// 02 · PT — PENETRANTONDERZOEK",
 "ndt_pt_p": "Een vloeibare penetrant dringt door capillaire werking in aan het oppervlak uitkomende scheuren; na het afwassen en aanbrengen van een ontwikkelaar wordt de indicatie naar buiten getrokken en zichtbaar gemaakt. Onmisbaar voor niet-magnetische materialen (roestvast staal, aluminium, koperlegeringen).",
 "ndt_pt_sub": "Penetrantonderzoek",
 "ndt_pt_st1": "Oppervlaktereiniging",
 "ndt_pt_st2": "Aanbrengen penetrant",
 "ndt_pt_st3": "Inwerktijd (≥ 20 min)",
 "ndt_pt_st4": "Afwassen & ontwikkelaar",
 "ndt_pt_st5": "Inspectie & registratie",
 "ndt_pt_d1": "Aan het oppervlak uitkomende scheuren (warm, koud)",
 "ndt_pt_d2": "Aan het oppervlak uitkomende poriën en kraters",
 "ndt_pt_d3": "Niet-versmolten naadlijnen",
 "ndt_pt_d4": "Fijne oppervlaktefouten (&gt;1 µm)",
 "ndt_pt_c1": "Detectie oppervlaktescheuren",
 "ndt_pt_c2": "Toepasbare materialen",
 "ndt_pt_c3": "Volumetrische detectie",
 "ndt_mt_i": "// 03 · MT — MAGNETISCH ONDERZOEK",
 "ndt_mt_p": "Wanneer een magnetisch veld op ferromagnetisch materiaal wordt aangebracht, worden ijzerdeeltjes aangetrokken door de lekflux rond fouten aan en net onder het oppervlak (2–3 mm). Heeft op koolstofstaal en laaggelegeerd staal de voorkeur boven PT.",
 "ndt_mt_sub": "Magnetisch onderzoek",
 "ndt_mt_st1": "Magnetisatie met juk",
 "ndt_mt_st2": "Aanbrengen deeltjes (nat/droog)",
 "ndt_mt_st3": "Inspectie onder UV-/wit licht",
 "ndt_mt_st4": "Demagnetisatie",
 "ndt_mt_st5": "Registratie",
 "ndt_mt_d1": "Scheuren aan en net onder het oppervlak",
 "ndt_mt_d2": "Koude overlapping",
 "ndt_mt_d3": "Porieclusters net onder het oppervlak (ondiep)",
 "ndt_mt_d4": "Wals-/dubbelingsfouten",
 "ndt_mt_c1": "Net onder oppervlak (≤2mm)",
 "ndt_ut_i": "// 04 · UT — ULTRASOON (IN EIGEN HUIS)",
 "ndt_ut_p": "Hoogfrequente geluidsgolven bewegen door het materiaal en worden gereflecteerd wanneer zij een discontinuïteit (fout, binnenoppervlak) tegenkomen. De veiligste en meest economische methode om volumetrische (inwendige) fouten op te sporen. Bij dikke platen is het veel veiliger dan RT (geen straling). <strong>Uitgevoerd door ons personeel gecertificeerd volgens ISO 9712 niveau II</strong> — rapportage in eigen huis.",
 "ndt_ut_sub": "Ultrasoon onderzoek",
 "ndt_ut_st1": "Kalibratie (referentieblok)",
 "ndt_ut_st2": "Scannen (A-scan puls-echo)",
 "ndt_ut_st3": "Echobeoordeling",
 "ndt_ut_st4": "Foutgrootte & -positie",
 "ndt_ut_st5": "Rapport & goed-/afkeur",
 "ndt_ut_d1": "Inwendige scheuren (alle oriëntaties)",
 "ndt_ut_d2": "Onvolledige doorlassing, bindingsfouten",
 "ndt_ut_d3": "Volumetrische fouten (grote poriën, slakinsluitingen)",
 "ndt_ut_d4": "Dubbelingen (walsen)",
 "ndt_ut_d5": "Alle fouten die in ISO 5817 als volumetrisch zijn geclassificeerd",
 "ndt_ut_c1": "Detectie volumetrische fouten",
 "ndt_ut_c2": "Detectiediepte",
 "ndt_ut_c3": "Oppervlaktefouten",
 "ndt_rt_i": "// 05 · RT — RADIOGRAFIE (OPNAME: PARTNER · BEOORDELING: IN EIGEN HUIS)",
 "ndt_rt_p": "Röntgen- of gammastraling gaat door het materiaal en wordt bij fouten anders verzwakt, waardoor deze zichtbaar worden op film of digitale detectoren. De filmopname wordt uitgevoerd door een vergund partnerbedrijf; de filmbeoordeling en rapportage worden gedaan door ons eigen RT-personeel gecertificeerd volgens EN ISO 9712 niveau 2, en de rapporten worden aan uw opdrachtdossier toegevoegd.",
 "ndt_rt_sub": "Radiografisch onderzoek",
 "ndt_rt_st1": "Voorbereiding bron & veiligheid van de zone",
 "ndt_rt_st2": "Plaatsing film / digitale detector",
