 "ndt_rt_d4": "Reacties en onregelmatigheden aan het binnenoppervlak",
 "ndt_rt_c1": "Detectie volumetrische fouten",
 "ndt_rt_c2": "Oppervlaktefouten",
 "ndt_rt_c3": "Dikteonafhankelijkheid",
 "ndt_foot_in": "UITGEVOERD IN EIGEN HUIS",
 "ndt_foot_out": "OPNAME: VERGUNDE PARTNER · BEOORDELING: NIVEAU 2 IN EIGEN HUIS",
 "ndt_foot_op": "● OPERATIONEEL",
 "ndt_foot_partner": "● PARTNERLAB",
 "ndt_def1_h": "Scheur",
 "ndt_def1_p": "Een scheiding veroorzaakt door verlies van samenhang. Kan warm (stolling) of koud (waterstof) geïnduceerd zijn. De gevaarlijkste foutklasse.",
 "ndt_def2_h": "Porositeit",
 "ndt_def2_p": "Bolvormige holten veroorzaakt door gas dat tijdens het stollen is ingesloten. Voorkomen door zuiver beschermgas, droge elektroden en een schoon oppervlak.",
 "ndt_def3_h": "Slakinsluiting",
 "ndt_def3_p": "Slakresten die in de las achterblijven door onvoldoende reiniging tussen de lagen. Voorkomen door gedisciplineerd slijpen/borstelen bij meerlaags lassen.",
 "ndt_def4_h": "Bindingsfout",
 "ndt_def4_p": "Het niet bereiken van volledige versmelting tussen toevoegmateriaal en basismateriaal of tussen de lagen. Veroorzaakt door te lage stroom of een onjuiste techniek.",
 "ndt_def5_h": "Onvolledige doorlassing",
 "ndt_def5_p": "Het niet volledig doorlassen van de grondlaag over de gehele materiaaldikte. Treedt op bij een onjuiste vooropeningshoek, vooropening of onjuiste grondlaagparameters.",
 "ndt_def6_h": "Inkarteling",
 "ndt_def6_p": "Een kerf/groef in het basismateriaal aan de lasteen. Veroorzaakt door te hoge stroom of een onjuiste toortshoek. Beginpunt van vermoeiingsscheuren.",
 "ndt_accept_lede": "Niet elke opdracht wordt met dezelfde strengheid onderzocht. Afhankelijk van de constructieve risicoklasse wordt acceptatie volgens EN ISO 5817 niveau B, C of D toegepast. Tenzij anders vermeld, is de standaard van ArmaWeld het strengste niveau, B.",
