 "welding_mig_full": "MIG/MAG-lassen · ISO 4063 proces 131/135/136",
 "welding_mig_desc": "Een halfautomatisch proces met hoge neersmelt, waarbij een continu aangevoerde draad onder beschermgas wordt gebruikt. De ruggengraat van onze werkplaats; eerste keuze voor kraanconstructies, staalbouw en frames van grondverzetmachines.",
