 "blog_idx_title": "Technische blog — Lassen & metaalbewerking | ArmaWeld",
 "blog_idx_h1": "Technische artikelen.",
 "blog_idx_lede": "Vaknotities over lastechniek, NDO-onderzoeksmethoden en de fabricage van hoogsterktestaal.",
 "blog_card1_tag": "NDO · Niet-destructief onderzoek",
 "blog_card1_h2": "Wat is NDO? Vergelijking van de methoden VT, PT, MT, UT en RT",
 "blog_card1_p": "Vijf fundamentele niet-destructieve onderzoeksmethoden in de gelaste constructiebouw, wanneer u welke kiest en de certificeringseisen van EN ISO 9712.",
 "blog_card1_read": "Artikel lezen →",
 "blog_card2_tag": "Hoogsterktestaal",
 "blog_card2_h2": "Lasparameters S960QL: voorwarmen, warmte-inbreng en WPS",
 "blog_card2_p": "Kritische parameters voor het lassen van ultrahoogsterkte S960QL-staal: CEV-berekening, verplicht H5-toevoegmateriaal en beheersing van de tussenlaagtemperatuur.",
 "blog_card2_read": "Artikel lezen →",
 "blog_card3_tag": "Normen & certificering",
 "blog_card3_h2": "Wat is EN 1090 EXC3? Gids CE-markering voor staalconstructies",
 "blog_card3_p": "Het verschil tussen EN 1090-1 en EN 1090-2, de uitvoeringsklassen EXC1–EXC4 en de stappen die nodig zijn om CE-certificering te verkrijgen.",
 "blog_card3_read": "Artikel lezen →",
 "blog_ndt_title": "Wat is NDO? Vergelijking van VT, PT, MT, UT, RT | ArmaWeld Blog",
 "blog_ndt_tag": "NDO · Niet-destructief onderzoek",
 "blog_ndt_h1": "Wat is NDO? Vergelijking van VT, PT, MT, UT en RT",
 "blog_ndt_read": "8 min lezen",
 "blog_ndt_author": "ArmaWeld Engineering",
 "blog_ndt_breadcrumb3": "NDO-methoden",
 "blog_ndt_s0": "<p>Niet-destructief onderzoek (NDO) is de methode om de materiaalintegriteit van gelaste constructies, drukapparatuur en dragende constructies te onderzoeken zonder het onderdeel te beschadigen. EN ISO 9712 is het internationale referentiedocument dat de certificeringseisen voor NDO-personeel vastlegt.</p><p>De keuze van de NDO-methode in de gelaste constructiebouw wordt bepaald door het materiaaltype, de geometrie van het onderdeel, het verwachte fouttype en de toepasselijke norm.</p>",
 "blog_ndt_s1": "<h2>Vijf fundamentele NDO-methoden</h2><table class=\"comparison-table\"><thead><tr><th>Methode</th><th>Volledige naam</th><th>Detecteert</th><th>Beperkingen</th></tr></thead><tbody><tr><td>VT</td><td>Visueel onderzoek</td><td>Oppervlaktescheuren, porositeit, te hoge lasoverhoogte, fouten in de lasgeometrie</td><td>Alleen oppervlak; inwendige fouten niet zichtbaar</td></tr><tr><td>PT</td><td>Penetrantonderzoek</td><td>Aan het oppervlak uitkomende scheuren, porositeit, dubbelingen</td><td>Alleen naar het oppervlak open fouten; niet bruikbaar op poreuze materialen</td></tr><tr><td>MT</td><td>Magnetisch onderzoek</td><td>Scheuren en overlappingen aan en net onder het oppervlak (≤3 mm)</td><td>Alleen ferromagnetische materialen; werkt niet op aluminium of roestvast staal</td></tr><tr><td>UT</td><td>Ultrasoon onderzoek</td><td>Inwendige scheuren, bindingsfouten, dubbelingen, holten</td><td>Diepe inwendige fouten in dik materiaal; interpretatie afhankelijk van de operator</td></tr><tr><td>RT</td><td>Radiografisch onderzoek</td><td>Inwendige porositeit, slakinsluitingen, inkarteling, bindingsfouten</td><td>Stralingsvergunning vereist; scheuroriëntatie cruciaal; toegang van beide zijden</td></tr></tbody></table>",
 "blog_ndt_s2": "<h2>VT — Visueel onderzoek</h2><p><strong>VT (visueel onderzoek)</strong> is de eerste stap van elk NDO-onderzoek en wordt uitgevoerd volgens EN ISO 17637. Lasgeometrie, oppervlakteruwheid, spatten, verkleuring en visueel waarneembare scheuren worden beoordeeld.</p><p>VT moet altijd vóór de andere NDO-methoden worden uitgevoerd. Een las die visueel zou worden afgekeurd, wordt niet aan PT of UT onderworpen — dat bespaart zowel tijd als kosten.</p><div class=\"callout\"><p><strong>Acceptatiecriteria EN ISO 5817:</strong> De toelaatbare foutgrootten zijn gedefinieerd volgens laskwaliteitsniveau B, C of D. Kwaliteitsniveau B is doorgaans van toepassing onder EN 1090 EXC3.</p></div>",
 "blog_ndt_s3": "<h2>PT — Penetrantonderzoek</h2><p><strong>PT (penetrantonderzoek)</strong> wordt toegepast volgens EN ISO 3452-1. Fluorescerende of gekleurde (rood-wit) penetrantvloeistoffen worden gebruikt om aan het oppervlak uitkomende discontinuïteiten op te sporen.</p><p>Toepassingsstappen:</p><ol><li>Oppervlaktereiniging (olie, roest en verf verwijderd)</li><li>Aanbrengen van de penetrant en inwerktijd (doorgaans 10–30 min)</li><li>Verwijderen van overtollige penetrant</li><li>Aanbrengen van de ontwikkelaar</li><li>Visuele beoordeling (UV- of wit licht)</li></ol><p>PT is de voorkeursmethode voor oppervlakteonderzoek van aluminiumconstructies, waar MT niet kan worden toegepast.</p>",
 "blog_ndt_s4": "<h2>MT — Magnetisch onderzoek</h2><p><strong>MT (magnetisch onderzoek)</strong> wordt uitgevoerd volgens EN ISO 17638. In ferromagnetische materialen (koolstofstaal, laaggelegeerd staal) wordt een magnetisch veld opgewekt en concentreren ijzerpoeder of fluorescerende deeltjes zich boven fouten.</p><p><strong>Voordeel:</strong> Scheuren net onder het oppervlak (≤3 mm diep) worden veel betrouwbaarder gedetecteerd dan met PT. MT wordt onder EN 1090 EXC3 vaak vereist voor T-verbindingen en hoeklassen.</p><div class=\"callout\"><p><strong>Opmerking:</strong> MT kan niet worden toegepast op austenitisch roestvast staal of aluminium. Voor het oppervlakteonderzoek van deze materialen wordt <strong>PT</strong> gebruikt.</p></div>",
 "blog_ndt_s5": "<h2>UT — Ultrasoon onderzoek</h2><p><strong>UT (ultrasoon onderzoek)</strong> wordt uitgevoerd volgens EN ISO 11666. Hoogfrequente geluidsgolven worden door het materiaal gestuurd; reflecties veroorzaakt door inwendige fouten worden beoordeeld om de locatie en grootte van de fout te bepalen.</p><p>Moderne technieken zoals <span class=\"tag-inline\">TOFD</span> (Time-of-Flight Diffraction) en <span class=\"tag-inline\">Phased Array UT (PAUT)</span> bieden een aanzienlijk hogere betrouwbaarheid en registreerbaarheid dan conventioneel UT. Vooral geprefereerd voor lassen in drukvaten en pijpleidingen.</p>",
 "blog_ndt_s6": "<h2>RT — Radiografisch onderzoek</h2><p><strong>RT (radiografisch onderzoek)</strong> wordt uitgevoerd volgens EN ISO 17636-1. Röntgen- of gammastralen worden door de lasdoorsnede gestuurd om een beeld te vormen op film of een digitale detector.</p><p>RT toont volumetrische fouten zoals porositeit en slakinsluitingen zeer duidelijk, maar is voor het opsporen van vlakke scheuren minder betrouwbaar dan UT — omdat een scheur mogelijk niet wordt gedetecteerd als zijn oriëntatie evenwijdig loopt aan de stralingsrichting.</p>",
 "blog_ndt_s7": "<h2>Certificeringsniveaus EN ISO 9712</h2><p>NDO-personeel wordt volgens EN ISO 9712 op drie niveaus gecertificeerd:</p><ul><li><strong>Niveau 1:</strong> Voert onderzoek uit volgens een vastgelegde procedure; rapporteert niet zelfstandig. Werkt onder toezicht van ervaren personeel.</li><li><strong>Niveau 2:</strong> Stelt procedures op, voert onderzoek uit, beoordeelt de resultaten aan de norm en rapporteert. De branchestandaard voor praktiserende inspecteurs.</li><li><strong>Niveau 3:</strong> Zet het NDO-systeem op, keurt procedures en technische instructies goed, examineert personeel van niveau 1 en 2. Bevoegdheid op engineeringniveau.</li></ul><p>Bij ArmaWeld worden VT-, PT-, MT- en UT-onderzoek uitgevoerd door ons eigen personeel dat is <strong>gecertificeerd volgens EN ISO 9712 niveau 2</strong>. RT-diensten worden geleverd via onze geaccrediteerde laboratoriumpartner.</p>",
 "blog_ndt_cta_h3": "Informatie over NDO-diensten",
 "blog_ndt_cta_p": "Neem contact op met ons technisch team om te bepalen welke NDO-methode uw project vereist.",
