 "blog_wps_title": "Wat is een WPS? Gids voor de lasmethodebeschrijving | ArmaWeld Blog",
 "blog_wps_meta_desc": "De verplichte grondslag van een WPS, de inhoud, de relatie met de WPQR en het kwalificatieproces volgens EN ISO 15614-1. WPS-portfolio van ArmaWeld.",
 "blog_wps_og_title": "Wat is een WPS? Gids lasmethodebeschrijving | ArmaWeld",
 "blog_wps_tag": "Normen & Certificering",
 "blog_wps_h1": "Wat is een WPS? Gids voor de lasmethodebeschrijving",
 "blog_wps_read": "9 min leestijd",
 "blog_wps_author": "ArmaWeld Engineering",
 "blog_wps_breadcrumb3": "Wat is een WPS?",
 "blog_wps_s0": "<p>Een lasmethodebeschrijving (WPS, Welding Procedure Specification) is het technische document dat vastlegt hoe een bepaalde lasverbinding moet worden gemaakt. De parameters die erin staan — proces, materiaalgroep, diktebereik, laspositie, toevoegmateriaal, beschermgas, voorwarm- en tussenlaagtemperatuur — vormen het kader waaraan de lasser zich tijdens de productie moet houden.</p><p>Een WPS is verplicht bij elke productie die wordt uitgevoerd volgens EN ISO 3834-2 en EN 1090 EXC2/3/4. Lassen met een niet-goedgekeurde WPS kan de certificering en CE-markering van de constructie ongeldig maken.</p>",
 "blog_wps_s1": "<h2>Verplichte grondslag van een WPS</h2><p>De WPS-eis vloeit voort uit meerdere normen:</p><ul><li><span class=\"tag-inline\">EN ISO 3834-2</span> — Onder de uitgebreide kwaliteitseisen is een goedgekeurde WPS verplicht.</li><li><span class=\"tag-inline\">EN 1090-2</span> — Voor elk lasproces in uitvoeringsklasse EXC2 en hoger is een WPS vereist.</li><li><span class=\"tag-inline\">EN 13445</span> — Aan drukvaten mag niet worden gelast zonder een combinatie van WPS + WPQR.</li><li><span class=\"tag-inline\">PED 2014/68/EU</span> — Goedkeuring van de lasmethode is verplicht voor drukapparatuur van categorie II en hoger.</li></ul><p>Een WPS is dus niet zomaar een regel; het is de technische basis die de betrouwbaarheid van de constructie aantoont.</p>",
 "blog_wps_s2": "<h2>Wat staat er in een WPS?</h2><table class=\"data-table\"><thead><tr><th>Onderdeel</th><th>Inhoud</th></tr></thead><tbody><tr><td>Algemene gegevens</td><td>WPS-nummer, revisie, WPQR-referentie, opstellende ingenieur</td></tr><tr><td>Basismateriaal</td><td>Materiaalnorm, staalgroep (ISO/TR 15608), diktebereik</td></tr><tr><td>Lasproces</td><td>Procescode (bijv. 135 MAG, 141 TIG), één-/meerlaags, laspositie</td></tr><tr><td>Toevoegmateriaal</td><td>Norm, classificatie, diameter, klasse diffundeerbaar waterstof (H5 enz.)</td></tr><tr><td>Beschermgas</td><td>Samenstelling (% Ar/CO₂), debiet (l/min)</td></tr><tr><td>Elektrische parameters</td><td>Stroomsterkte (A), spanning (V), polariteit, voortloopsnelheid (cm/min), warmte-inbreng (kJ/mm)</td></tr><tr><td>Thermische condities</td><td>Voorwarmtemperatuur (°C), max. tussenlaagtemperatuur (°C), PWHT</td></tr><tr><td>Lasnaadvoorbewerking</td><td>Naadvorm, openingshoek, vooropening, staande kant</td></tr></tbody></table>",
 "blog_wps_s3": "<h2>Relatie met de WPQR</h2><p>Een WPS moet gebaseerd zijn op een <strong>WPQR (lasmethodekwalificatie)</strong>, een experimenteel gevalideerd document. De volgorde is:</p><ol><li><strong>pWPS (voorlopige WPS)</strong> wordt opgesteld — een concept van de ingenieur op basis van technische kennis.</li><li><strong>Kwalificatielas</strong> wordt gemaakt — met proefstukken voor destructief onderzoek.</li><li><strong>Destructieve proeven</strong> worden uitgevoerd — trek-, buig-, hardheids-, Charpy- en macro-onderzoek.</li><li><strong>WPQR</strong> wordt opgesteld — ondertekend door een onafhankelijke goedkeurende instantie (aangemelde instantie of geaccrediteerd laboratorium).</li><li><strong>WPS</strong> wordt goedgekeurd met verwijzing naar de WPQR en in productie gebruikt.</li></ol><div class=\"callout\"><p><strong>Belangrijk:</strong> Het geldigheidsgebied van de WPS wordt afgeleid van de beproevingscondities in de WPQR. Een WPQR die op 12 mm is gemaakt, kan bijvoorbeeld een bereik van 6–24 mm dekken; 25 mm valt er echter niet onder.</p></div>",
 "blog_wps_s4": "<h2>Het WPS-portfolio van ArmaWeld</h2><p>ArmaWeld beheert een brede bibliotheek van goedgekeurde WPS-documenten volgens EN ISO 15614-1 (staal) en EN ISO 15614-2 (aluminium). Deze bibliotheek dekt de volgende materiaalgroepen: constructiestaal S235–S960QL en Strenx 700/900/960/1100, drukvatenstaal P265GH/P355NH, austenitisch roestvast staal 304L/316L, slijtvast staal HARDOX 400/450/500 en de aluminiumlegeringen EN AW-5754/6082. Bij de start van elk nieuw project controleert de lasingenieur de toepasbaarheid van de WPS; wordt het bereik overschreden, dan wordt een nieuw pWPS- en WPQR-traject gestart.</p>",
 "blog_wps_cta_h3": "Bekijk ons WPS-portfolio",
 "blog_wps_cta_p": "Deel het materiaal en het diktebereik van uw project; wij reageren binnen 48 uur met de toepasselijke goedgekeurde WPS.",
