 "home_aud3_d": "EXC3-constructiestaal, montageondersteuning en montageklare onderdelenpakketten.",
 "home_blog_eyebrow": "08 / Technische inzichten",
 "home_blog_h2": "Notities uit de <span style=\"color:var(--arc-2)\">lastechniek.</span>",
 "home_blog1_t": "Wat zijn WPS en WPQR?",
 "home_blog1_d": "Een las zonder goedgekeurde methode — het eerste struikelblok bij een audit.",
 "home_blog2_t": "EN 1090 EXC3 in de praktijk",
 "home_blog2_d": "Wat productiebeheersing, traceerbaarheid en het CE-dossier werkelijk vereisen.",
