 "home_blog3_d": "VT, PT, MT, UT — welke methode voor welke fout.",
 "home_certs_eyebrow": "09 / Certificeringen",
 "home_certs_h2": "De <span style=\"color:var(--arc-2)\">documentaire ruggengraat</span> van auditeerbare productie.",
 "home_certs_lede": "Elk project is gebouwd op goedgekeurde WPS'en, gecertificeerd personeel en traceerbare kwaliteitsregistraties. De onderstaande normen worden actief onderhouden.",
 "home_certs_link": "Kwaliteitsproces en documentenpakket →",
 "proj1_outcome": "Seriematige bakkenproductie met reproduceerbare WPS en VT/MT-plan per onderdeel.",
 "proj2_outcome": "Hoofddraagconstructie van een magazijn met EXC2/EXC3-dossier en maatrapport.",
 "proj3_outcome": "Reactor onder PED met TIG/MIG-WPS, 100% RT en CE-dossier.",
 "proj4_outcome": "PV-constructie met thermisch verzinkte coating, controle van snijtoleranties en montageondersteuning.",
 "proj5_outcome": "Draaistelframe met EN 15085 CL1-registratieketen en 100% UT.",
 "proj6_outcome": "Bordes, trappen en leuningen — geleverd met montagelijst en oppervlaktevoorbehandeling.",
 "services_s01_benefit": "Elke las geregistreerd met goedgekeurde WPS.",
 "services_s02_benefit": "Lasklare kanten en tolerantiecontrole.",
 "services_s03_benefit": "Montagepassing door zetsimulatie.",
 "why_eyebrow": "07 / Waarom ArmaWeld",
 "why_h2": "Procedurediscipline, <span style=\"color:var(--arc-2)\">geen marketing.</span>",
 "why1_t": "EN ISO 3834-2-kader",
 "why1_d": "Laskwaliteitsmanagement is dagelijkse routine — geen speciale projectmodus.",
 "why2_t": "EXC3-constructiestaal",
 "why2_d": "Productiebeheersing, traceerbaarheid en CE-dossier uit één gegevensketen.",
 "why3_t": "4 NDO-methoden in eigen huis",
 "why3_d": "VT, PT, MT, UT — personeel niveau 2; RT via partner indien vereist.",
 "why4_t": "Offerte-SLA van 48 uur",
 "why4_d": "Materiaal- en methodekeuzes staan zwart op wit in de offerte — geen mondelinge beloften.",
 "footer_capability": "EN ISO 3834-2 · EN 1090 EXC3 · 4 NDO-methoden · offerte binnen 48 uur",
 "cap_title_tag": "Productiecapaciteit — ArmaWeld | EN 1090 EXC3 · EN ISO 3834-2",
 "cap_meta_desc": "Productiecapaciteit van ArmaWeld: EN 1090 EXC3-constructiestaal, EN ISO 3834-2-laskwaliteit, materiaalgroepen, NDO en offerte binnen 48 uur. Vestiging Konya.",
 "cap_h1": "Productiecapaciteit<br/><span class=\"arc\">Konya · geïntegreerde locatie</span>",
 "cap_updated": "Laatst bijgewerkt: mei 2026",
 "cap_intro": "Deze pagina vat samen wat wij daadwerkelijk produceren in onze vestiging in Konya. Wij delen certificaten, materiaal-/procesbereik en de workflow van offerte tot levering — geen opgeblazen machinelijst.",
 "cap_cert_h": "Certificaten & bereik",
 "cap_cert_p": "EN 1090-2 EXC3 (constructiestaal), EN ISO 3834-2 (laskwaliteit), ISO 9001:2015 (kwaliteit), ISO 14001:2015 (milieu), ISO 45001:2018 (arbeidsveiligheid en gezondheid). WPS-bibliotheek op basis van WPQR; lassers EN ISO 9606-1/2. NDO-personeel EN ISO 9712 niveau 2.",
 "cap_mat_h": "Materiaalgroepen",
 "cap_mat_p": "S235–S960QL, slijtvast staal Strenx/HARDOX, S700MC, roestvast staal 304/316L en geselecteerde aluminiumlegeringen — goedgekeurde WPS en warmtebeheersing per groep.",
 "cap_proc_h": "Processen",
 "cap_proc_p": "MIG/MAG, TIG, SMAW; CNC-plasma-/laser-/guillotinesnijden; zetten op de kantbank; mechanische montage. VT, PT, MT, UT op kritieke lassen; RT via partnerlaboratorium.",
 "cap_sla_h": "Offerte & levering",
 "cap_sla_p": "Schriftelijke offerte gemiddeld binnen 48 uur na beoordeling van de tekening: materiaal, WPS-samenvatting, NDO-plan en levertijd. NDA standaard; coördinatie van exportverzending mogelijk.",
 "cap_contact_h": "Technische bestanden sturen",
 "cap_contact_p": "Gebruik het contactformulier of info@armaweld.com met DWG/DXF/PDF en materiaalgegevens — engineering reageert binnen 48 uur.",
 "footer_cap_link": "Capaciteitsprofiel →",
 "services_cta_p": "Stuur tekeningen of een monster — wij stellen binnen 48 uur een kostenanalyse en een productieplan op.",
 "footer_legal": "De inhoud, afbeeldingen en handelsmerken op deze website zijn eigendom van ArmaWeld. Reproductie of gebruik zonder toestemming is verboden.",
 "home_ref_q1": "Eerdere leveranciers sloegen bij het lassen van S960QL het voorwarmen over — wij kregen scheuren. Bij ArmaWeld waren de WPS en het voorwarmprotocol compleet.",
 "home_ref_q1_who": "INKOOPMANAGER · OEM ZWARE VOERTUIGEN",
 "home_ref_q2": "Wij vroegen het EN 1090 EXC3-documentenpakket op. CE-dossier, WPQR-lijst, NDO-registraties — alles lag bij de eerste levering klaar.",
 "home_ref_q2_who": "KWALITEITSINGENIEUR · ENERGIECENTRALE",
 "home_ref_q3": "Wij plaatsen al drie jaar elk jaar serieorders voor bakken. De kwaliteitsvariatie per onderdeel is vrijwel nul — die discipline is moeilijk vol te houden.",
 "home_ref_q3_who": "ALGEMEEN DIRECTEUR · MACHINEBOUW",
