 "services_saw_h2": "35 m onderpoederdek-<br/>laslijn.",
 "services_saw_desc": "Onze nieuwe onderpoederdeklasmachine van 35 meter last lange lineaire naden, gieken van machines en kranen, en chassis van opleggers en machines in één opspanning, met constante parameters en volgens een gekwalificeerde WPS.",
 "services_saw_f1": "Lange lineaire naden: liggers, kokerprofielen, platen en tankmantels",
 "services_saw_f2": "Gieklassen: gieken van bouwmachines, kranen en hoogwerkers",
 "services_saw_f3": "Chassislassen: opleggers, landbouw- en bouwmachines",
 "services_saw_f4": "Kwaliteitskader EN ISO 3834-2, parameterregistratie en NDO",
