 "kf_title": "Uitbesteed laswerk in Konya, Turkije | Lassen in onderaanneming — ArmaWeld",
 "kf_meta_desc": "Uitbesteed laswerk in Konya, Turkije: chassis, gieken, staalconstructies en machineonderdelen gelast volgens uw tekeningen. EN 1090 EXC3- en ISO 3834-2-gecertificeerd MIG/MAG, TIG en SAW. Offerte binnen 48 uur.",
 "kf_og_title": "Uitbesteed laswerk in Konya, Turkije | ArmaWeld",
 "kf_breadcrumb": "Uitbesteed laswerk Konya",
 "kf_label": "Konya, Turkije · Productie in onderaanneming",
 "kf_h1": "Uitbesteed <span>laswerk</span><br>in Konya",
 "kf_lead": "Gelaste constructiebouw in onderaanneming vanuit Konya, met EN 1090- en ISO 3834-2-gecertificeerde productie. MIG/MAG-, TIG- en robotlassen voor OEM's.",
 "kf_cta_all": "Alle diensten",
