 "exp_cta_portal": "Klantenportaal",
 "exp_s1_label": "Waarom Turkije, waarom ArmaWeld?",
 "exp_s1_title": "Europese normen, Turkse kostenbasis",
 "exp_s1_desc": "Dezelfde normen, dezelfde documenten, dezelfde acceptatiecriteria. Het verschil zit in capaciteit en kostenflexibiliteit, zonder concessies aan de documentatiediscipline. Tot op heden hebben wij geproduceerd voor bedrijven in Oostenrijk, Duitsland, Luxemburg en Noorwegen.",
 "exp_c1_icon": "CE",
 "exp_c1_h": "Certificaten geldig voor de EU-markt",
 "exp_c1_p": "EN 1090-2 EXC3-fabrieksproductiebeheersing en CE-prestatieverklaring; EN ISO 3834-2-laskwaliteit; managementsystemen ISO 9001, 14001 en 45001.",
 "exp_c2_icon": "EN",
 "exp_c2_h": "Offerte, documenten en portaal in het Engels",
 "exp_c2_p": "WPS, WPQR, 3.1-certificaten, NDO- en maatrapporten worden in het Engels opgesteld; het klantenportaal is 24/7 beschikbaar met een Engelstalige interface.",
 "exp_c3_icon": "QT",
 "exp_c3_h": "Expertise in hoogsterktestaal",
 "exp_c3_p": "Volgens EN ISO 15614-1 gekwalificeerde WPQR's voor S690QL, S960QL, Strenx 700/960/1100, S700MC en HARDOX; registratie van voorwarm- en tussenlaagtemperatuur.",
 "exp_c4_icon": "1 contract",
 "exp_c4_h": "Capaciteit zonder investering, één verantwoordelijke",
 "exp_c4_p": "Eén contract, één prijs, één levertijd van materiaal tot verzending. Snijden, zetten, lassen, NDO, schilderen en voormontage in de werkplaats onder verantwoordelijkheid van ArmaWeld; montage op locatie maakt geen deel uit van de omvang.",
 "exp_c5_icon": "Logistiek",
 "exp_c5_h": "Logistiek van Konya naar Europa",
 "exp_c5_p": "Over de weg van Centraal-Anatolië naar Europa, over zee wereldwijd via de haven van Mersin. EXW- of DAP-opties in de offerte; de exportdocumenten worden door ArmaWeld verzorgd.",
 "exp_c6_icon": "NDA",
 "exp_c6_h": "Geheimhouding en bescherming van het ontwerp",
 "exp_c6_p": "Een NDA is standaard bij elk project; uw tekeningen en productgegevens worden uitsluitend voor uw order gebruikt. Langlopende raamovereenkomsten zijn mogelijk.",
 "exp_s2_label": "Exportvoorwaarden",
 "exp_s2_title": "Samenvatting voor Europese inkopers",
 "exp_s2_desc": "Punten die in de offertefase worden vastgelegd; projectspecifieke voorwaarden worden in het contract opgenomen.",
