 "cut_s3_label": "Proces",
 "cut_s3_title": "Zo werken wij",
 "cut_st1_h": "Tekening en snijplan",
 "cut_st1_p": "Uw DXF/STEP-bestand wordt beoordeeld op maakbaarheid; snijplan, zetvolgorde en lasnaadvoorbewerking worden door ArmaWeld opgesteld.",
 "cut_st2_h": "Materiaal en snijden",
 "cut_st2_p": "Plaat wordt ingekocht met 3.1-certificaten; het laser- of plasmasnijden gebeurt bij een partnerbedrijf volgens het snijplan van ArmaWeld.",
 "cut_st3_h": "Zetten en ingangscontrole",
 "cut_st3_p": "De gezette onderdelen komen aan bij ArmaWeld; hoek, maat en oppervlak worden gecontroleerd en afwijkende onderdelen bereiken het lassen nooit.",
 "cut_st4_h": "Lassen, inspectie en levering",
 "cut_st4_p": "Lassen volgens goedgekeurde WPS, NDO en maatrapport; schilderen en montage indien vereist. Het onderdeel wordt montageklaar geleverd met zijn documentdossier.",
 "cut_s4_label": "Typische onderdelen",
 "cut_s4_title": "Voor welke onderdelen is dit bedoeld?",
 "cut_s4_desc": "Voor elk onderdeel dat na het snijden en zetten moet worden gelast; orders voor alleen snijden of alleen zetten kunnen ook worden geoffreerd.",
 "cut_sec1_h": "Beugels en consoles",
 "cut_sec1_p": "Gezette beugels, verbindingsplaten",
 "cut_sec2_h": "Kasten en behuizingen",
 "cut_sec2_p": "Plaatstalen kasten, afdekkingen, afschermingen",
 "cut_sec3_h": "Kokerliggers en profielen",
 "cut_sec3_p": "Gezette kokerprofielen, U- en C-profielen",
 "cut_sec4_h": "Tanks en trechters",
 "cut_sec4_p": "Gewalste mantels, conische trechters",
 "cut_sec5_h": "Machineonderdelen",
 "cut_sec5_p": "Framedelen, steunen, opspanmiddelen",
 "cut_sec6_h": "Seriematige plaatdelen",
 "cut_sec6_p": "Herhaalbare batches, voorzien van serienummer",
 "cut_s5_label": "Veelgestelde vragen",
 "cut_s5_title": "FAQ snijden en zetten",
 "cut_f1_q": "Worden het lasersnijden en zetten bij ArmaWeld zelf uitgevoerd?",
 "cut_f1_a": "Snijden en zetten worden uitgevoerd bij partnerbedrijven die ArmaWeld selecteert en auditeert, volgens onze eigen specificatie; het snijplan, de materiaalinkoop en de ingangscontrole zijn van ArmaWeld. Lassen, NDO en montage gebeuren in eigen huis, en ArmaWeld is verantwoordelijk voor de kwaliteit van de hele keten.",
 "cut_f2_q": "Kan ik alleen snijden of alleen zetten bestellen?",
 "cut_f2_a": "Ja, dat kan worden geoffreerd. Het echte voordeel is echter het plannen van snijden, zetten en lassen in één order: één prijs, één levertijd en montageklare onderdelen.",
 "cut_f3_q": "Welke bestandsformaten accepteren jullie?",
 "cut_f3_a": "DXF, DWG, STEP en PDF. Voor onderdelen zonder tekening meten wij het monster op en stellen wij de werkplaatstekening op.",
 "cut_f4_q": "Hoe worden de zettoleranties gecontroleerd?",
 "cut_f4_a": "Elk gezet onderdeel wordt bij de ingangscontrole van ArmaWeld gecontroleerd op hoek en maten; de meetwaarden, opgenomen met gekalibreerde meetmiddelen, worden onder het serienummer geregistreerd. Afwijkende onderdelen worden niet gelast.",
 "cut_f5_q": "Wat hebben jullie nodig voor een offerte?",
 "cut_f5_a": "Technische tekening (DXF/DWG/STEP/PDF), materiaalkwaliteit en dikte, aantal, vereiste oppervlaktebehandeling en, indien van toepassing, kwaliteitsklasse en NDO-eisen. Offerte binnen 48 uur.",
