 "nf_code": "Fout 404 · Pagina niet gevonden",
 "nf_h1": "De pagina die u zoekt, is hier niet.",
 "nf_lead": "Mogelijk is de pagina verplaatst of hernoemd, of heeft deze nooit bestaan. U kunt verdergaan via de onderstaande links.",
 "nf_home": "Terug naar Home →",
 "nf_popular": "Populaire pagina's",
 "nf_ndt": "NDO · Niet-destructief onderzoek",
 "pg_belgelerimiz_title": "Certificaten — ArmaWeld",
 "pg_belgelerimiz_desc": "De officiële certificaten van ArmaWeld: bekijk en download EN 1090-2 EXC3, EN ISO 3834-2, ISO 9001:2015, ISO 14001:2015 en ISO 45001:2018.",
 "pg_hakkimizda_title": "Over ons | Gelaste constructiebouw in Konya, Turkije — ArmaWeld",
 "pg_hakkimizda_desc": "Het team van ArmaWeld: lasingenieurs, NDO-technici en gecertificeerde lassers die als één interdisciplinair team werken.",
 "pg_hizmetler_title": "Diensten gelaste constructiebouw | MIG/MAG, TIG, SAW, lasersnijden, zetten — ArmaWeld",
 "pg_hizmetler_desc": "Onze diensten in gelaste constructiebouw: MIG/MAG- en TIG-lassen, 35 m onderpoederdeklassen, lasersnijden, CNC-zetten, mechanische montage en NDO. Gecertificeerd volgens EN 1090-2, ISO 3834-2, ISO 9001, 14001, 45001.",
 "pg_iletisim_title": "Contact & offerte | Gelaste constructiebouw in Konya, Turkije — ArmaWeld",
 "pg_iletisim_desc": "Deel uw technische gegevens en ontvang binnen 48 uur antwoord. Snel offerteformulier voor materiaal, dikte en toepassing.",
 "pg_index_title": "Gelaste constructiebouw in Konya, Turkije | EN 1090 — ArmaWeld",
 "pg_index_desc": "Gelaste constructiebouw, uitbesteed laswerk en NDO in Konya, Turkije, met export naar Europa. MIG/MAG, TIG, 35 m onderpoederdeklassen, lasersnijden, CNC-zetten. EN 1090-2 EXC3 CE, EN ISO 3834-2 gecertificeerd; levering EXW/DAP.",
 "pg_kalite_title": "Kwaliteit & traceerbaarheid | EN ISO 3834-2, WPS en NDO-rapporten — ArmaWeld",
 "pg_kalite_desc": "Productie gecertificeerd volgens EN 1090-2 EXC3, EN ISO 3834-2, ISO 9001:2015, ISO 14001:2015, ISO 45001:2018, EN ISO 15614-1/2 en EN ISO 9606-1/2, met volledige traceerbaarheid.",
 "pg_kaynak_title": "MIG/MAG- & TIG-lasdiensten | Professionele gelaste constructiebouw — ArmaWeld",
 "pg_kaynak_desc": "MIG/MAG- en TIG-lasdiensten: EN ISO 3834-2-gecertificeerde industriële productie met gekwalificeerde lassers, projectmatig of in serie. Vraag een offerte aan.",
 "pg_ndt_title": "NDO-diensten in Konya, Turkije | VT, PT, MT, UT — ArmaWeld",
 "pg_ndt_desc": "Niet-destructief onderzoek met VT, PT, MT, UT en RT, uitgevoerd door personeel gecertificeerd volgens EN ISO 9712 niveau 2.",
 "pg_projeler_title": "Projecten | Gelaste constructiebouw en staalbouw — ArmaWeld",
 "pg_projeler_desc": "Geselecteerde referentieprojecten in grondverzetmachines, staalbouw, energie, spoor en procesapparatuur, met materiaal, lasproces en NDO-scope.",
 "pg_sektorler_title": "Sectoren: machinebouw, staalbouw, drukvaten, energie | ArmaWeld",
 "pg_sektorler_desc": "Gelaste constructiebouw voor bouwmachines, transport en logistiek, energie-infrastructuur en industriële installaties. S700MC, HARDOX, P355GH en meer.",
 "pg_sss_title": "FAQ | Uitbesteed laswerk & gelaste constructiebouw — ArmaWeld",
 "pg_sss_desc": "Veelgestelde vragen en technische antwoorden over lasnormen, staalgroepen, certificaatscopes en productieprocessen.",
 "px_hz_1": "Uitbesteed laswerk",
