 "px_hz_14": "■ ONDERPOEDERDEKLASSEN · SAW",
 "px_hz_15": "UITBESTEED · MIG/MAG- & TIG-LASSEN · PROJECTMATIGE PRODUCTIE",
 "px_hz_16": "Uitbesteed laswerk.<br/><span>Projectmatige industriële oplossingen.</span>",
 "px_hz_18": "Van uw tekening tot levering: uitbesteed laswerk en projectmatige productie. MIG/MAG- en TIG-lassen, gecertificeerd volgens EN 1090 en ISO 3834-2, met door engineering geoptimaliseerde kosten en gecertificeerde kwaliteit.",
 "px_hz_19": "Gecertificeerde productieopzet",
 "px_hz_20": "Met het laskwaliteitsmanagement volgens EN ISO 3834-2 en de EN 1090 EXC3-certificering wordt elk onderdeel met traceerbare registraties geproduceerd.",
 "px_hz_21": "MIG/MAG- & TIG-lassen",
 "px_hz_22": "MIG/MAG- en TIG-fabricage met goedgekeurde WPS in koolstofstaal, roestvast staal, aluminium en hoogsterktestaal.",
 "px_hz_23": "Projectmatige flexibiliteit",
 "px_hz_24": "Wij plannen de productie van enkele prototypes tot middelgrote series. Er geldt geen minimale afname.",
 "px_hz_25": "Geoptimaliseerde kosten & transparante offertes",
 "px_hz_26": "Engineeringdiscipline verhoogt de operationele efficiëntie; onnodige kosten worden geëlimineerd en u ontvangt een transparante, concurrerende offerte.",
 "px_hz_27": "Volledig geïntegreerd proces",
 "px_hz_28": "Lassen, NDO en schilderen in eigen huis; plaatsnijden en zetten worden binnen de projectplanning gecoördineerd. Eén aanspreekpunt en traceerbare levering.",
 "px_hz_29": "Toezicht door ingenieurs",
 "px_hz_30": "Elk uitbesteed project krijgt een kwaliteitsplan onder leiding van een IWE/IWT-gecertificeerde ingenieur, en de lasparameters worden geregistreerd.",
 "px_hz_31": "Productieproces: van tekening tot levering",
 "px_hz_32": "Technische beoordeling & offerte",
 "px_hz_33": "Wij beoordelen de tekening of het monster, bepalen materiaalgroep, lasproces (MIG/MAG of TIG), toleranties en documentatie, en stellen vervolgens de offerte op.",
 "px_hz_34": "WPS-selectie & productieplan",
 "px_hz_35": "Een goedgekeurde lasprocedure (WPS/WPQR) wordt geselecteerd en er wordt een productieplan met lasvolgorde en inspectiepunten opgesteld.",
 "px_hz_36": "Lassen & NDO",
 "px_hz_37": "Gekwalificeerde lassers voeren het MIG/MAG- of TIG-lassen uit en het vereiste NDO (UT, MT, PT, VT) wordt toegepast.",
 "px_hz_38": "Nadat maatcontroles, visuele inspectie en kwaliteitsregistraties zijn afgerond, worden de onderdelen verzonden met de fabricagedocumentatie.",
 "px_hz_39": "Welk lasproces past bij uw project?",
 "px_hz_40": "MIG/MAG-lassen",
