 "px_hz_54": "Hoog (robotgeschikt)",
 "px_hz_55": "Gemiddeld",
 "px_hz_56": "Veelgestelde vragen",
 "px_hz_57": "Wat is uitbesteed laswerk?",
 "px_hz_58": "Het is contractproductie waarbij het lasbedrijf onderdelen bouwt volgens de tekeningen of monsters van de klant, met eigen apparatuur en gekwalificeerde lassers. ArmaWeld levert dit met goedgekeurde WPS volgens EN 1090 en ISO 3834-2.",
 "px_hz_59": "Geldt er een minimale afname voor projectmatige fabricage?",
 "px_hz_60": "ArmaWeld verzorgt zowel enkele prototypes als serieproductie. Er geldt geen minimale afnamehoeveelheid (MOQ); het productieplan volgt de eisen van het project.",
 "px_hz_61": "Wat is het verschil tussen MIG/MAG- en TIG-lassen?",
 "px_hz_62": "MIG/MAG (ISO 4063: 135/136) is ideaal voor productief seriewerk en heeft de voorkeur voor constructiestaal. TIG (ISO 4063: 141) geeft superieure kwaliteit op roestvast staal, aluminium en dunwandige precisieonderdelen. ArmaWeld past beide toe met goedgekeurde WPS en gekwalificeerde lassers.",
 "px_hz_63": "Welke documenten levert u bij uitbesteed laswerk?",
 "px_hz_64": "EN ISO 3834-2-laskwaliteitscertificaat, EN 1090 EXC3-certificaat voor de uitvoeringsklasse, goedgekeurde WPS/WPQR, lasserskwalificatiecertificaten en, op verzoek, NDO-rapporten (UT, MT, PT).",
 "px_hz_65": "Welke sectoren bedient u?",
 "px_hz_66": "Wij leveren uitbesteed laswerk en projectmatige oplossingen aan fabrikanten in machinebouw, bouw en staalconstructies, landbouwmachines, defensie, energie, hydrauliek en speciale industriële apparatuur.",
 "px_hz_67": "(200 mm, projectmatig)",
