 "pt_how2_h": "Productiedata stroomt binnen",
 "pt_how2_p": "Elke werkorder wordt geopend met een digitaal serienummer; materiaal-, WPS-, lasser-, NDO- en maatregistraties bereiken het portaal tijdens de productie.",
 "pt_how3_h": "U volgt mee",
 "pt_how3_p": "De positie van uw order op de lijn met 7 fasen, de verwachte levering en een eventueel vertragingsrisico zijn weken van tevoren zichtbaar, niet pas op de verzenddag.",
 "pt_how4_h": "Het dossier blijft paraat",
