 "pt_s_panel_h": "Dashboard",
 "pt_s_panel_p": "Zodra u inlogt, staat een overzicht van al uw orders voor u klaar.",
 "pt_s_panel_list": "<ul><li>Aantallen orders in productie, gereed voor verzending, afgerond en in totaal</li><li>Lijst “Actie vereist”: items die op uw goedkeuring wachten en leveringsbevestigingen</li><li>Vanaf elke kaart met één klik naar de bijbehorende order</li></ul>",
 "pt_s_panel_alt": "Scherm van het ArmaWeld-klantenportaal: Dashboard",
 "pt_img_panel": "/assets/portal/en/panel.jpg?r=3",
 "pt_s_takip_h": "Leverprestatie en live ordertracking",
