 "pt_s_takip_list": "<ul><li>Percentage tijdige leveringen, gemiddelde productievoortgang en komende leveringen</li><li>Een lijn met 7 fasen voor elke order: afgeronde, lopende en nog openstaande fasen</li><li>Statussen in productie, afgerond en geannuleerd in één oogopslag</li></ul>",
