 "pt_s_izlenebilirlik_list": "<ul><li>Operator, datum en notities in elke fase</li><li>Het WPS-nummer dat in de lasfase is gebruikt</li><li>Fasedocumenten (maatrapport, WPS, lasserskwalificatie): bekijken of downloaden</li></ul>",
