 "pt_s_belgeler_p": "Alle technische documenten en certificaten van uw orders in één archief.",
 "pt_s_belgeler_list": "<ul><li>WPS, WPQR, EN 10204 3.1-materiaalcertificaten, NDO-rapporten, lascertificaten, ingangscontrole- en maatrapporten</li><li>Filteren per order</li><li>Bekijken en downloaden als ondertekende pdf's</li></ul>",
