 "pt_s_mesajlar_h": "Ordergebonden berichten",
 "pt_s_mesajlar_p": "Uw gesprekken met het ArmaWeld-team blijven aan de opdracht gekoppeld in plaats van verloren te gaan in e-mailthreads.",
 "pt_s_mesajlar_list": "<ul><li>Elk gesprek gekoppeld aan een order en een onderwerp</li><li>Zoeken op onderwerp of ordernummer, filteren op ongelezen berichten</li><li>PDF-, afbeeldings-, Word- en Excel-bestanden bijvoegen</li></ul>",
 "pt_s_mesajlar_alt": "Scherm van het ArmaWeld-klantenportaal: Ordergebonden berichten",
 "pt_img_mesajlar": "/assets/portal/en/mesajlar.jpg?r=3",
 "pt_s_bildirimler_h": "Fase- en documentmeldingen",
