 "pt_s_bildirimler_list": "<ul><li>Meldingen “Fase bijgewerkt” en documentmeldingen</li><li>Aantal ongelezen en alles als gelezen markeren</li><li>Vanuit een melding rechtstreeks naar de orderpagina</li></ul>",
 "pt_s_bildirimler_alt": "Scherm van het ArmaWeld-klantenportaal: Fase- en documentmeldingen",
 "pt_img_bildirimler": "/assets/portal/en/bildirimler.jpg?r=3",
 "pt_s_teklif_h": "Offerteaanvragen vanuit het portaal (RFQ)",
 "pt_s_teklif_p": "Open offerteaanvragen voor nieuwe projecten in het portaal en volg het proces live.",
 "pt_s_teklif_list": "<ul><li>Nieuwe aanvraag door DWG / DXF / PDF te uploaden</li><li>Aanvraagstatus: in behandeling, offerte uitgebracht, omgezet in order, afgewezen</li><li>Aanvraaghistorie met indienings- en streefdatums</li></ul>",
 "pt_s_teklif_alt": "Scherm van het ArmaWeld-klantenportaal: Offerteaanvragen vanuit het portaal (RFQ)",
